import { readFile, writeFile } from 'node:fs/promises';
const html = await readFile(new URL('../public/vietnam-only.html', import.meta.url), 'utf8');
const handler = await readFile(new URL('../deploy/cloudflare-country-handler.js', import.meta.url), 'utf8');
await writeFile(new URL('../deploy/cloudflare-vietnam-worker.js', import.meta.url),
  '// Generated by node scripts/build-country-worker.js. Paste this entire file in Cloudflare Worker.\nconst PAGE = ' + JSON.stringify(html) + ';\n' + handler);
console.log('Generated deploy/cloudflare-vietnam-worker.js');
